-- =====================================================
-- ROMDOC DATABASE MIGRATION
-- Staff medical-folder audit role
--
-- File:
-- ROMDOC/database/52-staff-medical-folder-access.sql
--
-- Purpose:
-- Permit medical-folder audit events generated by
-- delegated staff members.
-- =====================================================

begin;

do $$
declare
  constraint_record record;
begin
  for constraint_record in
    select
      constraint_info.conname
    from pg_constraint
      as constraint_info
    inner join pg_class
      as table_info
      on table_info.oid =
        constraint_info.conrelid
    inner join pg_namespace
      as schema_info
      on schema_info.oid =
        table_info.relnamespace
    where schema_info.nspname =
        'public'
      and table_info.relname =
        'patient_medical_document_events'
      and constraint_info.contype =
        'c'
      and pg_get_constraintdef(
        constraint_info.oid
      ) ilike '%actor_role%'
  loop
    execute format(
      'alter table public.patient_medical_document_events drop constraint %I',
      constraint_record.conname
    );
  end loop;
end;
$$;

alter table
  public.patient_medical_document_events
add constraint
  patient_medical_document_events_actor_role_check
check (
  actor_role in (
    'patient',
    'doctor',
    'staff',
    'admin',
    'system'
  )
);

comment on constraint
  patient_medical_document_events_actor_role_check
on public.patient_medical_document_events is
  'Permitted audit actors, including delegated staff.';

commit;

select
  constraint_info.conname,
  pg_get_constraintdef(
    constraint_info.oid
  ) as definition
from pg_constraint
  as constraint_info
inner join pg_class
  as table_info
  on table_info.oid =
    constraint_info.conrelid
inner join pg_namespace
  as schema_info
  on schema_info.oid =
    table_info.relnamespace
where schema_info.nspname =
    'public'
  and table_info.relname =
    'patient_medical_document_events'
  and constraint_info.conname =
    'patient_medical_document_events_actor_role_check';
